def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    out = [row[:] for row in grid]

    # Locate the 5-by-3 colored motif; its center cell is the alignment point
    # for each marker (color 3).
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, 3)]
    if not cells:
        return out
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    motif = [row[c0:c1+1] for row in grid[r0:r1+1]]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                top, left = r - (r1-r0)//2, c - (c1-c0)//2
                for dr in range(len(motif)):
                    for dc in range(len(motif[0])):
                        rr, cc = top+dr, left+dc
                        if 0 <= rr < h and 0 <= cc < w and motif[dr][dc] != bg:
                            out[rr][cc] = motif[dr][dc]
                out[r][c] = bg
    return out
