def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    counts = Counter(v for row in grid for v in row if v != bg)
    marker = min(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] not in (bg, marker)]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    motif = [row[c0:c1+1] for row in grid[r0:r1+1]]
    ar, ac = (r1-r0)//2, (c1-c0)//2

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                top, left = r-ar, c-ac
                for dy, row in enumerate(motif):
                    for dx, value in enumerate(row):
                        rr, cc = top+dy, left+dx
                        if 0 <= rr < h and 0 <= cc < w and value != bg:
                            out[rr][cc] = value
    return out
